  // ─── Public lottery explainer ──────────────────────────────────────────────
  "lottery.title":            { en: "How the Lottery Works",  es: "Cómo Funciona el Sorteo" },
  "lottery.subtitle":         { en: "A clear, plain-language look at how we fairly fill seats when more families apply than we have room for.", es: "Una explicación clara y sencilla de cómo llenamos los cupos de manera justa cuando aplican más familias de las que tenemos espacio." },
  "lottery.whyTitle":         { en: "Why a lottery?",         es: "¿Por qué un sorteo?" },
  "lottery.whyBody":          { en: "When more families apply to a school than there are seats available, the law requires us to fill those seats through a fair random lottery — not on a first-come, first-served basis, and never by picking favorites.", es: "Cuando más familias solicitan una escuela de las que hay cupos disponibles, la ley nos exige llenar esos cupos mediante un sorteo aleatorio y justo — no por orden de llegada, y nunca eligiendo favoritos." },
  "lottery.step1Title":       { en: "You apply",              es: "Usted aplica" },
  "lottery.step1Desc":        { en: "The application is free and takes about 5 minutes. Applying early or late makes no difference in the lottery — every application has an equal chance.", es: "La solicitud es gratuita y toma unos 5 minutos. Aplicar temprano o tarde no hace ninguna diferencia en el sorteo — cada solicitud tiene la misma oportunidad." },
  "lottery.step2Title":       { en: "Every child gets a random number",  es: "Cada niño o niña recibe un número aleatorio" },
  "lottery.step2Desc":        { en: "On lottery day, every eligible child receives a random number from a published draw. Nobody chooses or influences the number — it's random for everyone.", es: "El día del sorteo, cada niño o niña elegible recibe un número aleatorio de un sorteo público. Nadie elige ni influye en el número — es aleatorio para todos." },
  "lottery.step3Title":       { en: "Seats fill by priority group, then by number", es: "Los cupos se llenan por grupo de prioridad, y luego por número" },
  "lottery.step3Desc":        { en: "Seats fill in priority-group order first (for example, siblings already at the school). Within each group, seats go purely by random number — lowest number first.", es: "Los cupos se llenan primero en el orden de los grupos de prioridad (por ejemplo, hermanos que ya asisten a la escuela). Dentro de cada grupo, los cupos se asignan puramente por número aleatorio — el número más bajo primero." },
  "lottery.step4Title":       { en: "You get an offer or a real place in line", es: "Usted recibe una oferta o un lugar real en la fila" },
  "lottery.step4Desc":        { en: "If there's a seat, you'll receive an offer. If not, your child goes on the waitlist with a real position you can see at any time — not a guess.", es: "Si hay un cupo, recibirá una oferta. Si no, su hijo/a queda en la lista de espera con una posición real que puede ver en cualquier momento — no es una suposición." },
  "lottery.priorityGroupsTitle": { en: "Priority groups by school", es: "Grupos de prioridad por escuela" },
  "lottery.tiersNote":        { en: "Each school's priority groups come from its authorizer-approved policy — the same rules for every family, published here for anyone to see.", es: "Los grupos de prioridad de cada escuela provienen de su política aprobada por el autorizador — las mismas reglas para cada familia, publicadas aquí para que cualquiera las vea." },
  "lottery.generalPool":      { en: "General pool",           es: "Grupo general" },
  "lottery.closesLine":       { en: "Applications close {date}; the lottery is held after that.", es: "Las solicitudes cierran el {date}; el sorteo se realiza después de esa fecha." },
  "lottery.promisesTitle":    { en: "Our promises to you",    es: "Nuestras promesas para usted" },
  "lottery.promise1":         { en: "The draw is reproducible — it can be independently checked and verified after the fact, so nothing is hidden.", es: "El sorteo es reproducible — puede ser revisado y verificado de forma independiente después, para que nada quede oculto." },
  "lottery.promise2":         { en: "Nobody can move a child up the list — not school staff, not us, not anyone.", es: "Nadie puede mover a un niño o niña hacia arriba en la lista — ni el personal de la escuela, ni nosotros, ni nadie." },
  "lottery.promise3":         { en: "Waitlisted families always see their live position — no wondering where you stand.", es: "Las familias en la lista de espera siempre ven su posición actual — sin tener que adivinar dónde están." },
  "lottery.faqTitle":         { en: "Frequently asked questions", es: "Preguntas frecuentes" },
  "lottery.faq1q":            { en: "Does applying early improve my chances?", es: "¿Aplicar temprano mejora mis posibilidades?" },
  "lottery.faq1a":            { en: "No. Every application submitted before the window closes has an equal chance, whether it's the first or the last one in.", es: "No. Toda solicitud enviada antes de que cierre el período tiene la misma oportunidad, ya sea la primera o la última en llegar." },
  "lottery.faq2q":            { en: "What if my child isn't selected?", es: "¿Qué pasa si mi hijo/a no es seleccionado/a?" },
  "lottery.faq2a":            { en: "Your child goes on a real waitlist with a live position you can check anytime. Seats open often, and waitlist families are contacted as soon as one does.", es: "Su hijo/a queda en una lista de espera real con una posición actual que puede consultar en cualquier momento. Los cupos se abren con frecuencia, y las familias en la lista de espera son contactadas tan pronto como uno se abre." },
  "lottery.faq3q":            { en: "Can anyone skip the line?", es: "¿Puede alguien saltarse la fila?" },
  "lottery.faq3a":            { en: "No. Priority groups — like sibling priority — are set by each school's public, authorizer-approved policy, not by staff discretion. Within a group, order is decided purely by random number.", es: "No. Los grupos de prioridad — como la prioridad para hermanos — se establecen mediante la política pública de cada escuela, aprobada por el autorizador, no a discreción del personal. Dentro de un grupo, el orden se decide puramente por número aleatorio." },
  "lottery.faq4q":            { en: "How do I know it's fair?", es: "¿Cómo sé que es justo?" },
  "lottery.faq4a":            { en: "The draw is reproducible: the same random number is produced every time it's re-run with the published inputs, so the results can be independently audited and verified after the fact.", es: "El sorteo es reproducible: el mismo número aleatorio se genera cada vez que se vuelve a ejecutar con los datos publicados, de modo que los resultados pueden ser auditados y verificados de forma independiente después." },
  "lottery.faq5q":            { en: "Do I need documents to apply?", es: "¿Necesito documentos para aplicar?" },
  "lottery.faq5a":            { en: "No. The application itself needs no documents. Paperwork like birth certificates and proof of residency is only collected later, after your child is offered a seat.", es: "No. La solicitud en sí no requiere documentos. Papeles como el acta de nacimiento y el comprobante de domicilio se recopilan más adelante, después de que a su hijo/a se le ofrezca un cupo." },
  "lottery.faq6q":            { en: "Is it really free?", es: "¿Es realmente gratis?" },
  "lottery.faq6a":            { en: "Yes. We're a free public school, and the application itself never costs anything.", es: "Sí. Somos una escuela pública gratuita, y la solicitud en sí nunca tiene ningún costo." },
  "lottery.ctaTitle":         { en: "Ready to get started?", es: "¿Listo/a para comenzar?" },
  "lottery.ctaBody":          { en: "Applying takes about 5 minutes, and there's no cost and no obligation.", es: "La solicitud toma unos 5 minutos, y no tiene costo ni obligación." },
